_PANEL_CACHE = {}


def panel(name):
    """Decode one embedded panel (cached)."""
    if name not in _PANEL_CACHE:
        _PANEL_CACHE[name] = Image.open(
            io.BytesIO(base64.b64decode(PANELS_B64[name]))).convert("RGB")
    return _PANEL_CACHE[name]


def fit_panel(name, w, h):
    return ImageOps.fit(panel(name), (w, h), Image.LANCZOS)


# ---------------------------------------------------------------- fonts
FONT_DIR = "/usr/share/fonts/truetype/noto/"
_FALLBACK = "/usr/share/fonts/truetype/dejavu/"


def font(name, size):
    for base in (FONT_DIR, _FALLBACK):
        p = Path(base) / name
        if p.exists():
            return ImageFont.truetype(str(p), size)
    return ImageFont.load_default()


