def rot_point(px, py, w, h, angle_deg, cx, cy):
    """Map a point from sheet-local coords to canvas coords after the same
    rotate(angle, expand=True) + centre-paste used for compositing.
    Verified empirically: PIL rotate uses
    x' = dx*cos + dy*sin ; y' = -dx*sin + dy*cos (y-down coords)."""
    th = math.radians(angle_deg)
    dx, dy = px - w / 2.0, py - h / 2.0
    return (cx + dx * math.cos(th) + dy * math.sin(th),
            cy - dx * math.sin(th) + dy * math.cos(th))


def rot_bbox(box, spec):
    """Axis-aligned canvas bbox of a sheet-local box after rotation."""
    (w, h), (cx, cy), ang = spec
    x0, y0, x1, y1 = box
    pts = [rot_point(x, y, w, h, ang, cx, cy)
           for x, y in ((x0, y0), (x1, y0), (x0, y1), (x1, y1))]
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    return (min(xs), min(ys), max(xs), max(ys))


# Bounding-box registries for the anti-overlap check.
MAIN_TEXT = []   # (name, canvas bbox) — every text element on the main sheet
BG_ELEMS = []    # (name, canvas bbox) — every element on background sheets


def reg_main(name, box):
    MAIN_TEXT.append((name, (round(box[0], 1), round(box[1], 1),
                             round(box[2], 1), round(box[3], 1))))


def reg_bg(name, box):
    BG_ELEMS.append((name, (round(box[0], 1), round(box[1], 1),
                             round(box[2], 1), round(box[3], 1))))


def mbox(local_box):
    """Main-sheet local box -> canvas box."""
    x0, y0, x1, y1 = local_box
    return (x0 + MAIN_X0, y0 + MAIN_Y0, x1 + MAIN_X0, y1 + MAIN_Y0)


def overlaps(a, b):
    return not (a[2] <= b[0] or b[2] <= a[0] or a[3] <= b[1] or b[3] <= a[1])


# ---------------------------------------------------------------- text utils
def wrap(text, fnt, width, draw):
    words = text.split()
    lines, cur = [], ""
    for w in words:
        trial = (cur + " " + w).strip()
        if draw.textlength(trial, font=fnt) <= width or not cur:
            cur = trial
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines


def text_block(draw, x, y, lines, fnt, fill, leading, name=None, xoff=0,
               yoff=0):
    """Draw left-aligned lines; register the block bbox (canvas coords)."""
    maxw = 0
    for i, ln in enumerate(lines):
        draw.text((x, y + i * leading), ln, font=fnt, fill=fill)
        maxw = max(maxw, draw.textlength(ln, font=fnt))
    if name:
        reg_main(name, (x + xoff, y + yoff, x + xoff + maxw,
                        y + yoff + len(lines) * leading))
    return len(lines) * leading


