# ---------------------------------------------------------------- flat art
def art_horn(d, x, y, w, h):
    """Sunset over the Horn: orange sky, sun, dark ridges."""
    for i in range(h):
        t = i / max(1, h - 1)
        d.line([(x, y + i), (x + w, y + i)],
               fill=(int(232 - 90 * t), int(122 - 40 * t), int(48 + 40 * t)))
    d.ellipse([x + w - 34, y + 6, x + w - 10, y + 30], fill=(255, 214, 120))
    d.polygon([(x, y + h), (x + w * 0.3, y + h * 0.45),
               (x + w * 0.55, y + h), ], fill=(94, 52, 44))
    d.polygon([(x + w * 0.4, y + h), (x + w * 0.7, y + h * 0.55),
               (x + w, y + h)], fill=(60, 34, 40))
    d.rectangle([x, y, x + 78, y + 11], fill=(30, 22, 20))
    d.text((x + 4, y + 1), "TROOPS MASSED", font=F_SANS_BOLD(9),
           fill=(255, 220, 150))


