# ---------------------------------------------------------------- main sheet
def draw_tag_row(d, x, y, w, num, region, topic, proof, small=False):
    """Region chip (left) + proof tag (right). Returns row height."""
    chip = f"{num} · {region} · {topic}"
    fnt = F_SANS_BOLD(9 if small else 10)
    tw = d.textlength(chip, font=fnt)
    col = REGION_COLORS[region]
    d.rectangle([x, y, x + tw + 12, y + 14], fill=col)
    d.text((x + 6, y + 2), chip, font=fnt, fill=(255, 255, 255))
    pf = F_SANS_BOLD(8 if small else 9)
    pw = d.textlength(proof, font=pf)
    d.text((x + w - pw - 2, y + 2), proof, font=pf, fill=(70, 68, 64))
    reg_main(f"tag{num}", mbox((x, y, x + w, y + 14)))
    return 14


def draw_lead(d, x, y, w, h, card):
    num, region, topic, proof, head, deck, art = card
    d.rectangle([x, y, x + w - 1, y + h - 1], fill=(255, 255, 255),
                outline=(30, 30, 30), width=1)
    ph = 78
    d.rectangle([x + 1, y + 1, x + w - 2, y + ph], fill=(20, 20, 20))
    d._image.paste(fit_panel(art, w - 2, ph - 1), (x + 1, y + 1))
    ty = y + ph + 2
    draw_tag_row(d, x + 5, ty, w - 10, num, region, topic, proof)
    hy = ty + 16
    hf = F_SERIF_BOLD(22)
    lines = wrap(head, hf, w - 12, d)[:3]
    text_block(d, x + 6, hy, lines, hf, INK, 22, name=f"lead{num}head",
               xoff=MAIN_X0, yoff=MAIN_Y0)
    dy = hy + len(lines) * 22 + 2
    df = F_SANS(12)
    dlines = wrap(deck, df, w - 12, d)[:2]
    text_block(d, x + 6, dy, dlines, df, (50, 48, 44), 13,
               name=f"lead{num}deck", xoff=MAIN_X0, yoff=MAIN_Y0)


def draw_medium(d, x, y, w, h, card):
    num, region, topic, proof, head, deck, art = card
    d.rectangle([x, y, x + w - 1, y + h - 1], fill=(255, 255, 255),
                outline=(30, 30, 30), width=1)
    ah = 52
    if art.startswith("art:"):
        FLAT_ART[art[4:]](d, x + 1, y + 1, w - 2, ah - 1)
    else:
        d._image.paste(fit_panel(art, w - 2, ah - 1), (x + 1, y + 1))
    ty = y + ah + 2
    draw_tag_row(d, x + 4, ty, w - 8, num, region, topic, proof, small=True)
    hy = ty + 15
    hf = F_SERIF_BOLD(16)
    lines = wrap(head, hf, w - 10, d)[:3]
    text_block(d, x + 5, hy, lines, hf, INK, 16.5, name=f"med{num}head",
               xoff=MAIN_X0, yoff=MAIN_Y0)
    dy = hy + len(lines) * 16.5 + 2
    df = F_SANS(11)
    dlines = wrap(deck, df, w - 10, d)[:2]
    text_block(d, x + 5, dy, dlines, df, (50, 48, 44), 12.5,
               name=f"med{num}deck", xoff=MAIN_X0, yoff=MAIN_Y0)


def draw_map(d, x, y, w, h):
    """Dotted world map + numbered pins + legend."""
    cols, rows = 56, 26
    cw, ch = w / cols, (h - 34) / rows
    dot = (178, 171, 158)
    for r, row in enumerate(WORLD_MAP):
        for c, ch_ in enumerate(row):
            if ch_ == "#":
                cx = x + c * cw + cw / 2
                cy = y + r * ch + ch / 2
                d.ellipse([cx - 1.5, cy - 1.5, cx + 1.5, cy + 1.5], fill=dot)
    pf = F_SANS_BLACK(8)
    for num, region, gc, gr in PINS:
        cx = x + gc * cw
        cy = y + gr * ch
        col = REGION_COLORS[region]
        d.ellipse([cx - 6.5, cy - 6.5, cx + 6.5, cy + 6.5], fill=col,
                  outline=(255, 255, 255), width=1)
        t = str(num)
        tw = d.textlength(t, font=pf)
        d.text((cx - tw / 2, cy - 5), t, font=pf, fill=(255, 255, 255))
    reg_main("mappins", mbox((x, y, x + w, y + h - 34)))
    # Legend: colour key + two explainer lines.
    lx, ly = x, y + h - 32
    kx = lx
    kf = F_SANS(9)
    for region, _ in REGION_COUNTS:
        d.ellipse([kx, ly + 1, kx + 7, ly + 8],
                  fill=REGION_COLORS[region])
        t = region.title()
        d.text((kx + 9, ly), t, font=kf, fill=(60, 58, 54))
        kx += 9 + d.textlength(t, font=kf) + 7
    reg_main("mapkey", mbox((lx, ly, lx + w, ly + 10)))
    lf = F_SANS(9)
    d.text((lx, ly + 11), "Pins 1–13 mark the cards above, coloured by region.",
           font=lf, fill=(60, 58, 54))
    d.text((lx, ly + 21), "Grey pin 3 is Voyager 1, in the north Pacific.",
           font=lf, fill=(60, 58, 54))
    reg_main("maplegend", mbox((lx, ly + 11, lx + w, ly + 31)))


def draw_tail_item(d, x, y, num, text):
    """One tail line: red number, bold lead, regular rest."""
    nf = F_SANS_BLACK(10)
    bf = F_SANS_BOLD(10)
    rf = F_SANS(10)
    n = f"{num} "
    d.text((x, y), n, font=nf, fill=RED)
    cx = x + d.textlength(n, font=nf)
    if ":" in text and text.index(":") <= 20:
        lead, rest = text.split(":", 1)
        lead += ":"
    else:
        parts = text.split(" ", 2)
        lead = " ".join(parts[:2])
        rest = " " + parts[2] if len(parts) > 2 else ""
    d.text((cx, y), lead, font=bf, fill=INK)
    cx += d.textlength(lead, font=bf)
    d.text((cx, y), rest, font=rf, fill=(40, 38, 34))
    w = cx + d.textlength(rest, font=rf) - x
    reg_main(f"tail{num}", mbox((x, y, x + w, y + 11)))


def draw_main_sheet():
    """Render the full front page on its own sheet image."""
    W, H = MAIN_W, MAIN_H
    im = Image.new("RGB", (W, H), PAPER)
    d = ImageDraw.Draw(im)
    d._image = im  # card painters paste photo panels via the draw object

    # ---- masthead (0..82)
    d.rectangle([0, 0, W, 82], fill=NAVY)
    d.rectangle([0, 0, 88, 82], fill=RED)
    d.text((16, 4), "NOV", font=F_SANS_BLACK(16), fill=(255, 255, 255))
    d.text((12, 20), "18", font=F_SANS_BLACK(44), fill=(255, 255, 255))
    d.text((10, 66), "WED · 2026", font=F_SANS_BOLD(10),
           fill=(255, 220, 210))
    reg_main("dateblock", mbox((0, 0, 88, 82)))
    d.text((100, 6), "THE DAY IN WORLD NEWS", font=F_SANS_BLACK(13),
           fill=GOLD)
    d.text((100, 22), "Wednesday 18 November 2026",
           font=F_SERIF_BLACK(40), fill=(255, 255, 255))
    d.text((100, 64),
           "Everything on this page happened, or was first reported, on "
           "Wednesday 18 November 2026.",
           font=F_SERIF_IT(13), fill=(207, 211, 224))
    tr = "40 STORIES · 7 REGIONS · ONE PAGE"
    tf = F_SANS_BOLD(11)
    d.text((W - d.textlength(tr, font=tf) - 10, 8), tr, font=tf,
           fill=(255, 255, 255))
    reg_main("masthead", mbox((100, 6, W - 10, 80)))

    # ---- region bar (82..100)
    seg = W / 7.0
    rf = F_SANS_BOLD(12)
    for i, (region, count) in enumerate(REGION_COUNTS):
        x0 = int(i * seg)
        x1 = int((i + 1) * seg)
        d.rectangle([x0, 82, x1, 100], fill=REGION_COLORS[region])
        t = f"{region} {count}"
        d.text((x0 + (x1 - x0 - d.textlength(t, font=rf)) / 2, 84), t,
               font=rf, fill=(255, 255, 255))
    reg_main("regionbar", mbox((0, 82, W, 100)))

    # ---- numbers strip (100..148)
    d.rectangle([0, 100, W, 148], fill=NUM_BG)
    d.line([(0, 100), (W, 100)], fill=(30, 30, 30), width=1)
    d.line([(0, 148), (W, 148)], fill=(30, 30, 30), width=1)
    nf = F_SANS_BLACK(12)
    d.text((8, 106), "THE DAY IN", font=nf, fill=RED)
    d.text((8, 120), "NUMBERS", font=nf, fill=RED)
    reg_main("numberslabel", mbox((8, 106, 90, 134)))
    cell_w = (W - 96) / 6.0
    ff = F_SANS_BLACK(23)
    cf = F_SANS(9.5)
    for i, (fig, cap) in enumerate(NUMBERS):
        cx0 = 96 + int(i * cell_w)
        cx1 = 96 + int((i + 1) * cell_w)
        if i:
            d.line([(cx0, 106), (cx0, 142)], fill=(200, 190, 160), width=1)
        d.text((cx0 + 8, 103), fig, font=ff, fill=RED)
        lines = wrap(cap, cf, cell_w - 16, d)[:2]
        for j, ln in enumerate(lines):
            d.text((cx0 + 8, 127 + j * 10), ln, font=cf, fill=(60, 58, 54))
        reg_main(f"num{i}", mbox((cx0, 104, cx1, 148)))

    # ---- leads (152..332)
    lw = 302
    for i, card in enumerate(LEADS):
        draw_lead(d, i * (lw + 7), 152, lw, 180, card)

    # ---- mediums (336..482, 486..632)
    mw = [179, 179, 179, 179, 180]
    xs = [0, 185, 370, 555, 740]
    for row, y0 in enumerate((336, 486)):
        for j in range(5):
            draw_medium(d, xs[j], y0, mw[j], 146,
                        MEDIUMS[row * 5 + j])

    # ---- tail header (636..652)
    hf = F_SANS_BLACK(12)
    d.line([(0, 636), (W, 636)], fill=(30, 30, 30), width=1)
    d.text((0, 639), "WHERE IT HAPPENED", font=hf, fill=INK)
    d.text((278, 639),
           "ALSO ON WEDNESDAY 18 NOVEMBER — 27 MORE STORIES",
           font=hf, fill=INK)
    reg_main("tailhead", mbox((0, 636, W, 652)))

    # ---- map + tail (652..808)
    draw_map(d, 0, 654, 270, 154)
    for k, (num, text) in enumerate(TAIL):
        col = 0 if k < 14 else 1
        row = k if k < 14 else k - 14
        draw_tail_item(d, 278 + col * 327, 654 + row * 11.1, num, text)

    # ---- date check (812..856)
    d.rectangle([0, 812, W - 1, 856], outline=RED, width=2)
    d.rectangle([0, 812, 92, 856], fill=RED)
    df = F_SANS_BLACK(12)
    d.text((8, 828), "DATE CHECK", font=df, fill=(255, 255, 255))
    reg_main("datechecklabel", mbox((0, 812, 92, 856)))
    tf = F_SANS(11.5)
    lines = wrap(DATE_CHECK, tf, W - 112, d)
    for j, ln in enumerate(lines):
        d.text((100, 816 + j * 13), ln, font=tf, fill=INK)
    reg_main("datecheck", mbox((100, 812, W - 8, 856)))

    # ---- footer (858..884)
    ff = F_SANS(10)
    d.text((0, 860), FOOTER_1, font=ff, fill=(60, 58, 54))
    d.text((0, 872), FOOTER_2, font=ff, fill=(60, 58, 54))
    reg_main("footer", mbox((0, 858, W, 884)))

    d.rectangle([0, 0, W - 1, H - 1], outline=(40, 36, 30), width=2)
    return im


