def _c_cx(y):
    """Centre x of the visible strip of sheet C at local height y."""
    return 265.6 - 0.0524 * y


def _c_text(d, text, y, fnt, leading, fill, name, width=92):
    """Centred wrapped text in sheet C's visible strip. Returns end y."""
    lines = wrap(text, fnt, width, d)
    min_x, max_x = 10 ** 9, -10 ** 9
    for j, ln in enumerate(lines):
        ly = y + j * leading
        tw = d.textlength(ln, font=fnt)
        lx = _c_cx(ly + leading / 2) - tw / 2
        d.text((lx, ly), ln, font=fnt, fill=fill)
        min_x, max_x = min(min_x, lx), max(max_x, lx + tw)
    reg_bg(name, rot_bbox((min_x, y, max_x, y + len(lines) * leading), BG_C))
    return y + len(lines) * leading


def _c_rule(d, y, half=46):
    cx = _c_cx(y)
    d.line([(cx - half, y), (cx + half, y)], fill=(150, 140, 120), width=1)


