# ---------------------------------------------------------------- composite
def paste_sheet(base, sheet, spec, shadow_alpha=130, shadow_off=(10, 12)):
    """Paste a rotated sheet with a soft drop shadow."""
    (w, h), (cx, cy), ang = spec
    mask = Image.new("L", (w, h), 0)
    ImageDraw.Draw(mask).rectangle([0, 0, w - 1, h - 1],
                                   fill=shadow_alpha)
    mask = mask.rotate(ang, resample=Image.BICUBIC, expand=True)
    mask = mask.filter(ImageFilter.GaussianBlur(8))
    full = Image.new("L", base.size, 0)
    full.paste(mask, (cx - mask.size[0] // 2 + shadow_off[0],
                      cy - mask.size[1] // 2 + shadow_off[1]))
    base.paste(Image.new("RGB", base.size, (0, 0, 0)), (0, 0), full)
    rot = sheet.convert("RGBA").rotate(ang, resample=Image.BICUBIC,
                                       expand=True)
    base.paste(rot, (cx - rot.size[0] // 2, cy - rot.size[1] // 2),
               rot.split()[3])
    return base


def build_table():
    """Dark tabletop: vertical gradient + corner vignette."""
    im = Image.new("RGB", (CANVAS, CANVAS), TABLE)
    d = ImageDraw.Draw(im)
    for yy in range(CANVAS):
        t = yy / (CANVAS - 1)
        d.line([(0, yy), (CANVAS, yy)],
               fill=(int(TABLE[0] + (TABLE_DK[0] - TABLE[0]) * t),
                     int(TABLE[1] + (TABLE_DK[1] - TABLE[1]) * t),
                     int(TABLE[2] + (TABLE_DK[2] - TABLE[2]) * t)))
    vig = Image.new("L", (CANVAS, CANVAS), 0)
    vd = ImageDraw.Draw(vig)
    for r in range(720, 0, -4):
        a = int(70 * (1 - r / 720) ** 2)
        vd.ellipse([512 - r, 512 - r, 512 + r, 512 + r], fill=a)
    im.paste(Image.new("RGB", (CANVAS, CANVAS), (0, 0, 0)), (0, 0), vig)
    return im


def verify_content():
    """Trap checks over every printed string in this file.

    The banned disease word must not appear at all; the stale-factories
    trap quote may appear exactly once, inside the DATE CHECK. (The search
    strings are built from parts so the banned word never appears as a
    literal anywhere in this source file.)
    """
    texts = [DATE_CHECK, FOOTER_1, FOOTER_2]
    for card in LEADS + MEDIUMS:
        texts += [card[3], card[4], card[5]]
    texts += [t for _, t in TAIL]
    for _, t in BG_HEADLINES_A + BG_HEADLINES_B + BG_HEADLINES_C:
        texts.append(t)
    blob = "\n".join(texts)
    banned = blob.count("Eb" "ola")
    stale = blob.count("55 factor" "ies shut")
    assert banned == 0, f"banned trap word appears {banned} times (must be 0)"
    assert stale == 1, (f"stale-factories trap quote appears {stale} "
                        "times (must be 1)")
    return banned, stale


def verify_overlap():
    """No background-sheet element may overlap any main-sheet text box."""
    bad = []
    for bname, bb in BG_ELEMS:
        for mname, mb in MAIN_TEXT:
            if overlaps(bb, mb):
                bad.append((bname, mname))
    return bad


def main():
    ebola, shut = verify_content()
    canvas = build_table()
    paste_sheet(canvas, draw_bg_sheet_a(), BG_A)
    paste_sheet(canvas, draw_bg_sheet_b(), BG_B)
    paste_sheet(canvas, draw_bg_sheet_c(), BG_C)
    main_sheet = draw_main_sheet()
    # Soft shadow under the main sheet, then the sheet itself.
    sh = Image.new("L", (MAIN_W, MAIN_H), 0)
    ImageDraw.Draw(sh).rectangle([0, 0, MAIN_W - 1, MAIN_H - 1], fill=140)
    sh = sh.filter(ImageFilter.GaussianBlur(10))
    full = Image.new("L", (CANVAS, CANVAS), 0)
    full.paste(sh, (MAIN_X0 + 8, MAIN_Y0 + 10))
    canvas.paste(Image.new("RGB", (CANVAS, CANVAS), (0, 0, 0)), (0, 0), full)
    canvas.paste(main_sheet, (MAIN_X0, MAIN_Y0))

    bad = verify_overlap()
    print(f"main text boxes: {len(MAIN_TEXT)}")
    print(f"background elements: {len(BG_ELEMS)}")
    print(f"overlaps (bg vs main text): {len(bad)}")
    for bname, mname in bad:
        print(f"  OVERLAP: {bname} x {mname}")
    print(f"trap check: banned word x{ebola}, stale-factories quote x{shut}")
    print(f"stories: {len(LEADS) + len(MEDIUMS) + len(TAIL)} "
          f"({len(LEADS)} leads + {len(MEDIUMS)} mediums + {len(TAIL)} tail)")
    assert not bad, "background element overlaps main-sheet text"
    out = Path(__file__).resolve().parent / "entry.png"
    canvas.save(out, "PNG")
    import hashlib
    print(f"wrote {out} sha256={hashlib.sha256(out.read_bytes()).hexdigest()}")


if __name__ == "__main__":
    main()
